import 'package:cloud_firestore/cloud_firestore.dart';
class AurenCalendarEvent{final String id,title,date,time;const AurenCalendarEvent({required this.id,required this.title,required this.date,required this.time});Map<String,dynamic> toMap()=>{'title':title,'date':date,'time':time,'createdAt':FieldValue.serverTimestamp()};static AurenCalendarEvent fromMap(String id,Map<String,dynamic> m)=>AurenCalendarEvent(id:id,title:m['title'] as String? ?? '',date:m['date'] as String? ?? '',time:m['time'] as String? ?? '');}
class CalendarService{final FirebaseFirestore db;CalendarService({FirebaseFirestore? firestore}):db=firestore??FirebaseFirestore.instance;CollectionReference<Map<String,dynamic>> _c(String u)=>db.collection('users').doc(u).collection('calendar_events');Stream<List<AurenCalendarEvent>> watch(String u)=>_c(u).orderBy('date').snapshots().map((s)=>s.docs.map((d)=>AurenCalendarEvent.fromMap(d.id,d.data())).toList());Future<void> create(String u,String t,String d,String time)async{final r=_c(u).doc();await r.set(AurenCalendarEvent(id:r.id,title:t.trim(),date:d,time:time).toMap());}Future<void> delete(String u,String id)=>_c(u).doc(id).delete();}